<div class="page-header"><div><span class="page-eyebrow">Customer Products</span><h2>Subscription Plans</h2><p>Manage customer-facing memberships, pricing and PayYantra checkout products.</p></div><a class="btn btn-primary" href="<?=htmlspecialchars(url('/admin/subscription-plans/create'))?>"><i data-lucide="plus"></i> New Plan</a></div>
<div class="admin-plan-grid"><?php foreach($plans as $plan): $benefits=json_decode($plan['benefits']??'[]',true)?:[];?><article class="admin-plan-card <?=$plan['featured']?'featured':''?>">
<header><div><small><?=htmlspecialchars($plan['category']??'Subscription')?></small><h3><?=htmlspecialchars($plan['name'])?></h3><p><?=htmlspecialchars($plan['subtitle']??ucwords(str_replace('_',' ',$plan['billing_cycle'])))?></p></div><span class="badge"><?=htmlspecialchars($plan['status'])?></span></header>
<div class="admin-plan-price"><strong>₹<?=number_format((float)$plan['price'],0)?></strong><span>/ <?=htmlspecialchars(str_replace('_',' ',$plan['billing_cycle']))?></span></div>
<?php if(!empty($plan['followup_payment'])):?><div class="plan-payment-note">₹<?=number_format((float)$plan['initial_payment'],0)?> now + ₹<?=number_format((float)$plan['followup_payment'],0)?> after <?=intval($plan['followup_due_days'])?> days</div><?php endif;?>
<ul><?php foreach(array_slice($benefits,0,4) as $benefit):?><li><i data-lucide="check"></i><span><?=htmlspecialchars(is_array($benefit)?($benefit['title']??''):$benefit)?></span></li><?php endforeach;?></ul>
<footer><a class="btn btn-sm" href="<?=htmlspecialchars(url('/admin/subscription-plans/edit/'.$plan['id']))?>"><i data-lucide="pencil"></i> Edit</a><?php if($plan['status']!=='archived'):?><form method="post" action="<?=htmlspecialchars(url('/admin/subscription-plans/archive/'.$plan['id']))?>"><?=csrf_field()?><button class="btn btn-sm" type="submit"><i data-lucide="archive"></i> Archive</button></form><?php endif;?></footer></article><?php endforeach;?></div>
